import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Συγκρούσεις και ελλιπείς αναθέσεις","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/dispatch-problems.md","filePath":"el/help/dispatch-problems.md"}'),s={name:"el/help/dispatch-problems.md"};function o(h,a,i,p,n,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="συγκρουσεις-και-ελλιπεις-αναθεσεις" tabindex="-1">Συγκρούσεις και ελλιπείς αναθέσεις <a class="header-anchor" href="#συγκρουσεις-και-ελλιπεις-αναθεσεις" aria-label="Permalink to &quot;Συγκρούσεις και ελλιπείς αναθέσεις&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="ο-οδηγος-η-το-οχημα-δεν-ειναι-διαθεσιμο" tabindex="-1">Ο οδηγός ή το όχημα δεν είναι διαθέσιμο <a class="header-anchor" href="#ο-οδηγος-η-το-οχημα-δεν-ειναι-διαθεσιμο" aria-label="Permalink to &quot;Ο οδηγός ή το όχημα δεν είναι διαθέσιμο&quot;">​</a></h2><p>Ελέγξτε περιοχή, κατάσταση οδηγού, βάρδιες, διαθεσιμότητα οχήματος, συντήρηση και αρχειοθέτηση. Εξετάστε χωρητικότητα επιβατών και αποσκευών. Ελέγξτε επικαλύψεις μαζί με το ρυθμισμένο χρονικό περιθώριο.</p><h2 id="δεν-επιτρεπεται-η-αναθεση-κρατησης" tabindex="-1">Δεν επιτρέπεται η ανάθεση κράτησης <a class="header-anchor" href="#δεν-επιτρεπεται-η-αναθεση-κρατησης" aria-label="Permalink to &quot;Δεν επιτρέπεται η ανάθεση κράτησης&quot;">​</a></h2><p>Ελέγξτε κατάσταση και προσφορά. Η εκκρεμής προσφορά εμποδίζει επιβεβαίωση και ανάθεση. Οι οριστικές κρατήσεις δεν επανενεργοποιούνται με συνήθη επεξεργασία. Επιβεβαιώστε τα δικαιώματα ανάθεσης.</p><h2 id="η-κρατηση-λειπει-απο-το-ημερολογιο" tabindex="-1">Η κράτηση λείπει από το ημερολόγιο <a class="header-anchor" href="#η-κρατηση-λειπει-απο-το-ημερολογιο" aria-label="Permalink to &quot;Η κράτηση λείπει από το ημερολόγιο&quot;">​</a></h2><p>Ελέγξτε ημερομηνία, περιοχή, προβολή ημέρας/εβδομάδας/μήνα και φίλτρο κατάστασης. Εξετάστε την κράτηση απευθείας πριν θεωρήσετε ότι αφαιρέθηκε. Μην δημιουργείτε διπλότυπο.</p><h2 id="ποτε-ζητατε-βοηθεια" tabindex="-1">Πότε ζητάτε βοήθεια <a class="header-anchor" href="#ποτε-ζητατε-βοηθεια" aria-label="Permalink to &quot;Πότε ζητάτε βοήθεια&quot;">​</a></h2><p>Αν δεν υπάρχουν διαθέσιμοι πόροι, αναδιοργανώστε τις αναθέσεις μέσω εγκεκριμένων διαδικασιών. Η παράκαμψη δεν υποκαθιστά ασφαλή χωρητικότητα ή επιχειρησιακή ετοιμότητα.</p><p>Δείτε <a href="/el/plus/assignments.html">Αναθέσεις</a>, <a href="/el/plus/dispatch-schedule.html">Πρόγραμμα</a> και <a href="/el/plus/fleet-management.html">Στόλος</a>.</p>',11)])])}const u=e(s,[["render",o]]);export{m as __pageData,u as default};
